window.REVIEW_DETAILS["ny_c-ddf2b08ee7205962"]={"key":"ny_c-ddf2b08ee7205962","group":"ny_c","uid":"ddf2b08ee7205962","rank":67,"title":"authored doc it diligence change of control 001","occupation":"computer_information_systems_managers","archetype":"authored_doc","subbatch":"corpus_c1","prompt":"You are Wilhelmina Arriaga, the technology diligence lead supporting Hester Kilbride on Stellwyn Advisory Group's investment committee review of its proposed acquisition of Cranmere Surveying. Greyhaven Freight and Pembroke Council are also involved in the wider portfolio discussion, so keep the named transaction and the audience unambiguous. The data room contains roughly 600 unorganised files, including licence registers, a vendor technology-diligence report, three years of contractor invoices, and Cranmere's risk log, but there is no supplied index or agreed buyer view. One easily missed invoice annex appears to concern an unassignable survey-processing licence that may terminate or require consent on a change of control; the committee is more likely to notice the larger, cleaner findings that may not change its vote. Viktor Delacroix, Noor Dalgaard, Idris Wolstenholme, and Felix Escamilla will use the material alongside finance, legal, operations, security, and the deal team. Prepare one PDF named `stellwyn_cranmere_it_diligence_committee.pdf` and place it at the top level of the working directory. It must contain a one-page IT diligence summary with integration conditions followed by exactly three presentation-style slides for the 4 September investment committee. Make one clear recommendation on whether to proceed, proceed only subject to conditions, or not proceed, and make the recommendation the ending decision rather than a list of future steps. Define the term “Day 1” before relying on it, because some readers use it for legal completion and others for the first operational day after completion; distinguish that transition state from the end-state technology model. Do not pretend that the data room proves facts it does not prove, do not invent purchase price, savings, incident, licence, headcount, or probability figures, and label assumptions, unknowns, dependencies, owners, timing, and escalation points plainly. Keep the summary to one page and the deck portion to three slides; write for executives who will not ask the author what a condition means, and leave out system click-throughs and a general catalogue of every data-room file.\n\n---\n\nWrite your finished work to the **top level of the current working directory**, using exactly these filenames:\n\n- `stellwyn_cranmere_it_diligence_committee.pdf` — A single PDF containing a one-page IT diligence summary with integration conditions and exactly three presentation-style slides for the investment committee. (The summary must occupy exactly one page.; The presentation portion must contain exactly three slides or three clearly separated slide pages.; The recommendation must be singular, explicit, and consistent across the summary and slides.; The document must distinguish evidence, assumptions, unknowns, conditions, owners, timing, and escalation.; The document must define Day 1 before using the term operationally.; The document must not invent unsupported transaction, financial, licensing, security, or operational facts.)\n\nNothing outside those filenames is collected. A correct file written anywhere else, or under any other name, scores zero.\n","inputs":[],"gold":[{"name":"package/private/gold/stellwyn_cranmere_it_diligence_committee.pdf","bytes":55819,"extension":".pdf","url":"assets/dac06e4e993901f8aa17866f586f3f981a58673eedc57ef7a50589ca9de7348f.pdf","sha256":"dac06e4e993901f8aa17866f586f3f981a58673eedc57ef7a50589ca9de7348f","preview":{"kind":"pdf","text":"IT DILIGENCE DECISION SUMMARY\n\nCranmere Surveying acquisition\n                                                                                               Prepared by Wilhelmina Arriaga for Hester Kilbride\n\n\n\nDECISION REQUESTED\n\nPROCEED ONLY SUBJECT TO CONDITIONS\nThe unresolved right to continue using the critical survey-processing capability after a change of control is material to\ncontinuity and must be closed or escalated before completion.\n\n\n\n  EVIDENCE BASIS AND LIMITS\n\n  Evidence reviewed: an unorganised data room of roughly 600 files, including licence registers, a vendor technology-diligence\n  report, contractor invoices and Cranmere's risk log. No complete buyer-validated inventory or agreed buyer view was supplied. The\n  invoice annex is a diligence lead, not proof of a contractual outcome.\n\n\n\nWORKING DEFINITIONS\n\nDay 1 means the first operational day after legal completion; it is not legal completion itself. Day 1 controls preserve service\nwhile ownership changes. The end-state technology model is the later, governed operating model once dependencies are\nresolved.\n\nPRIORITY FINDINGS — RANKED BY CONTINUITY IMPACT, TIMING AND REVERSIBILITY\n\n\n FINDING / EVIDENCE STATUS                 DECISION IMPACT                               REQUIRED CONDITION\n\n 1 Survey-processing licence               Loss or interruption could affect delivery    Legal + Technology: written assignability/consent\n Evidence: invoice annex signals a         of surveying work at the ownership            confirmation, or a documented replacement and\n possible unassignable or                  transition. A trigger does not prove          controlled fallback approved by the investment\n consent-dependent                         termination or block the transaction.         committee, before completion.\n change-of-control term.\n Unknown: contract wording,\n vendor position, renewal and\n replacement\n 2              feasibility.and data\n   Entitlement, third-party                Unclear lawful use, concentrated              Technology + Legal: validate software/technology\n dependencies                              knowledge or inaccessible project data        ownership and entitlement; identify contractor\n Evidence: registers and three years of    may delay safe integration and continuity.    access/knowledge dependencies; name data owners,\n contractor invoices exist; scope and                                                    retention and migration validation before Day 1.\n ownership have not been\n buyer-validated.\n\n 3 Security and resilience evidence        A control gap is not evidence of a breach.    Security + Operations: Day 1 identity/privileged-access\n gap                                       Uncontrolled access or untested recovery      review, critical application/data inventory, protected\n Evidence: vendor report and risk log      could amplify disruption during transition.   backup evidence and recovery test or approved interim\n are available; effectiveness of access,                                                 safeguard.\n recovery and critical-service controls\n remains unvalidated.\n\n\n\n  ESCALATION / DECISION GATE\n  If written consent/assignability confirmation or a committee-approved replacement-and-fallback package is not available before\n  completion, Hester Kilbride escalates to the Investment Committee to pause, renegotiate or explicitly accept residual risk. This is a\n  condition to proceed, not a post-close backlog item.\n\n\n\n\nStellwyn Advisory Group | Investment Committee | Cranmere Surveying                                      4 September | Executive summary | 1 of 4\n\f01 COMMITTEE DECISION\n\nA conditional decision protects continuity without overstating the evide\n Named transaction: Stellwyn Advisory Group's proposed acquisition of Cranmere Surveying | Audience: 4 September Investment Committee\n\n\n\n\n    RECOMMENDATION                                                     Why this posture\n\n\n    PROCEED ONLY SUBJECT TOThe evidence identifies a decision-relevant continuity uncertainty; it does not establish that the licence has\n                             CONDITIONS\n                           terminated, that a breach occurred, or that recovery works.\n\n\n\n\n   WHAT IS CONFIRMED                                                  WHAT IS UNKNOWN                                 WHAT MAKES IT DECISIVE\n\n   An invoice annex raises a change-of-control lead                   Contract interpretation, vendor consent,        If the capability cannot lawfully and reliably\n   for survey-processing software. Supporting records                 renewal/right to use, and the practical         continue through transition, operational surveying\n   are not yet a buyer-validated entitlement view.                    replacement/fallback position are unresolved.   continuity may be affected at completion.\n\n\n\n\nDECISION DISCIPLINE\n\n   Treat the licence as a pre-completion condition because its timing, reversibility and business dependency outrank cleaner descriptive observations.\n   Retain security, access, resilience, data and contractor work as defined transition conditions; do not convert evidence gaps into incident claims.\n   If the condition cannot be closed, take the explicit alternative back to the Investment Committee rather than silently moving it into integration.\n\n\n\n\n    DECISION: PROCEED ONLY SUBJECT TO CONDITIONS\n\n\n\n\nStellwyn Advisory Group | Investment Committee | Cranmere Surveying                                                                                4 September | Slide 1 — decision | 2 of 4\n\f02 CONDITIONS\n\nConditions, accountability and closure tests\n Conditions are separated from post-close improvement work. Owners are accountable functions, pending deal-team confirmation of named delegates.\n\n\n\n\n  CONDITION / PRIORITY                                     OWNER                   TIMING                   CLOSE WHEN                                             ESCALATE\n\n\n  P1 — Confirm survey-processing right to use after        Legal + Technology      Before completion        Written vendor/legal confirmation; or documented       Hester Kilbride → Investment\n  change of control; obtain consent, confirm                                                                replacement and transition control accepted by         Committee\n  assignability, or approve replacement + controlled                                                        Investment Committee.\n  fallback.\n\n\n\n\n  P2 — Protect critical operations: identify critical      Security + Operations   Before Day 1             Signed transition control pack, access review and      Technology diligence lead →\n  apps/data and owners; review joiner/leaver, shared and                                                    recovery test evidence — or expressly approved         deal lead\n  privileged access; evidence backup and recovery                                                           interim safeguard. A plan alone is not proof of\n  capability.                                                                                               tested recovery.\n\n\n\n\n  P2 — Validate entitlement/ownership, contractor          Technology + Legal +    Before Day 1; sequence   Validated inventory, dependency map, data              Deal lead → Investment\n  dependency and data access, retention and migration      Operations              migration post-close     owner/retention decision and protected migration       Committee if continuity is\n  validation scope.                                                                                         acceptance criteria.                                   threatened\n\n\n\n\n    POST-CLOSE IMPROVEMENT BACKLOG — NOT A CONDITION TO PROCEED\n\n    Move toward the end-state governance model only after the above gates: rationalise architecture, formalise service ownership and vendor management, and execute\n    approved data migration. These are not Day 1 promises.\n\n\n\n\nStellwyn Advisory Group | Investment Committee | Cranmere Surveying                                                                                4 September | Slide 2 — risks and conditions | 3 of 4\n\f03 TRANSITION AND TARGET STATE\n\nKeep the service operating while control changes; build the operating m\n Day 1 = first operational day after legal completion. It is an interim transition state, not the end-state architecture.\n\n\n\n\n   BEFORE COMPLETION                                  DAY 1 TRANSITION                            POST-CLOSE INTEGRATION                           END-STATE MODEL\n\n\n   Close licence condition                            Protect service continuity                  Validate and migrate safely                      Governed technology\n                                                                                                                                                   ownership\n   Vendor/legal confirmation or                       Retain approved survey-processing           Confirm data access, retention and\n   approved alternative; decide                       use/fallback; protect critical              migration acceptance; test recovery              Accountable service owners,\n   escalation if unresolved.                          apps/data; control identity, privileged     rather than relying on a written plan;           architecture governance, vendor\n                                                      and contractor access; maintain             reduce third-party knowledge                     management and a controlled\n                                                      backup evidence.                            concentration.                                   data/application model — sequenced\n                                                                                                                                                   after transition dependencies.\n\n\n\n\n    OPERATIONAL GUARDRAILS\n\n    Critical capability: do not switch off or migrate the survey-processing service             Evidence discipline: a licence trigger does not prove termination; an\n    solely because legal ownership changes. Maintain approved access and a                      access-control gap does not prove a breach; and a fallback plan does not prove\n    controlled fallback during transition.                                                      recoverability until it is evidenced or tested.\n\n\n\n\n    FINAL DECISION: PROCEED ONLY SUBJECT TO CONDITIONS.\n\n\n\nStellwyn Advisory Group | Investment Committee | Cranmere Surveying                                                                        4 September | Slide 3 — transition and end state | 4 of 4\n\f","truncated":false,"note":"PDF 文字提取；可打开原文件查看排版。"}}],"rubric":[{"rubric_item_id":"R01","check":"file_introspection","category":"deterministic","criterion":"A PDF named stellwyn_cranmere_it_diligence_committee.pdf is present and readable.","weight":1.0,"polarity":"credit","scaffolding":true,"cross_deliverable":false,"required":false,"evidence":"Submitted working-directory file and successful PDF text extraction.","grader_hint":"Check exact filename, PDF validity, and that text is selectable or otherwise inspectable."},{"rubric_item_id":"R02","check":"geometry","category":"deterministic","criterion":"The PDF contains exactly four pages: one summary page and three slide pages.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"PDF page count and rendered page review.","grader_hint":"Count pages and verify that page one is the summary and pages two through four are slide-style pages."},{"rubric_item_id":"R03","check":"constraint_predicate","category":"deterministic","criterion":"The first page is usable as a one-page executive IT diligence summary rather than a continuation of the slides.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Rendered first page.","grader_hint":"Judge whether a committee member can read page one as a self-contained summary without turning to the slides."},{"rubric_item_id":"R04","check":"judge","category":"semantic","criterion":"The artifact makes exactly one clear transaction recommendation.","weight":4.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Recommendation language on page one and slides.","grader_hint":"Accept one of proceed, proceed subject to conditions, or do not proceed; reject competing or unresolved alternatives."},{"rubric_item_id":"R05","check":"relational_predicate","category":"deterministic","criterion":"The same recommendation is stated consistently in the summary and all relevant slides.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Cross-page comparison.","grader_hint":"The conclusion and its qualification must not change between sections."},{"rubric_item_id":"R06","check":"substring","category":"deterministic","criterion":"The document defines Day 1 before using it as an operational milestone.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Definition and first subsequent use.","grader_hint":"Accept an explicit distinction between legal completion and the first operating day after completion, with the chosen meaning stated before operational requirements."},{"rubric_item_id":"R07","check":"relational_predicate","category":"deterministic","criterion":"The document distinguishes interim transition controls from the end-state technology operating model.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Transition and target-state passages.","grader_hint":"Look for separate treatment of what must work temporarily and what architecture, ownership, or process should exist after integration."},{"rubric_item_id":"R08","check":"substring","category":"deterministic","criterion":"The change-of-control or consent risk for the survey-processing software licence is identified as decision-relevant.","weight":4.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Risk statement and recommendation rationale.","grader_hint":"The licence must be described as potentially unassignable or consent-dependent on change of control, not merely as an ordinary licence inventory issue."},{"rubric_item_id":"R09","check":"relational_predicate","category":"deterministic","criterion":"The licence risk is connected to business continuity or transaction completion consequences.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Impact analysis and condition language.","grader_hint":"Look for the operational consequence of losing or lacking the software and why that affects the investment decision."},{"rubric_item_id":"R10","check":"substring","category":"deterministic","criterion":"The document requires confirmation of the licence's assignment, consent, renewal, or replacement position before the relevant transaction or operating milestone.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Integration condition.","grader_hint":"A vague recommendation to review contracts is insufficient; the condition must address the right to continue using the software after control changes."},{"rubric_item_id":"R11","check":"judge","category":"semantic","criterion":"The licence issue is prioritised above less decision-relevant descriptive findings when the evidence supports that prioritisation.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Risk ranking, decision rationale, and visual emphasis.","grader_hint":"Judge whether the artifact shows why a less legible but transaction-critical issue deserves committee attention."},{"rubric_item_id":"R12","check":"relational_predicate","category":"deterministic","criterion":"Each material finding states or clearly implies an impact, not merely an observation.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Finding table or narrative.","grader_hint":"Accept impacts such as continuity, legal execution, cyber exposure, cost, integration delay, or reputational risk when tied to a finding."},{"rubric_item_id":"R13","check":"relational_predicate","category":"deterministic","criterion":"Material findings are prioritised using a defensible business-decision basis.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Risk ranking or prioritisation rationale.","grader_hint":"Look for explicit or readily inferable consideration of severity, timing, reversibility, dependency, or decision impact."},{"rubric_item_id":"R14","check":"substring","category":"deterministic","criterion":"The document identifies the need to validate software and technology ownership or entitlement records.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Diligence finding or condition.","grader_hint":"The treatment should go beyond saying that a register exists and address whether records support lawful continued use."},{"rubric_item_id":"R15","check":"substring","category":"deterministic","criterion":"The document addresses third-party or contractor dependency as an integration risk where relevant.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Risk or condition section.","grader_hint":"Acknowledge access, knowledge concentration, continuity, or contractual dependency rather than merely mentioning invoices."},{"rubric_item_id":"R16","check":"substring","category":"deterministic","criterion":"The document addresses cyber or information-security exposure as a diligence dimension.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Risk assessment and condition language.","grader_hint":"Accept a proportionate treatment of controls, incidents, privileged access, resilience, or evidence gaps."},{"rubric_item_id":"R17","check":"relational_predicate","category":"deterministic","criterion":"Security concerns are not presented as proof of an incident or breach without evidence.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Wording of security findings.","grader_hint":"The document may identify exposure or an evidence gap, but must distinguish that from confirmed compromise."},{"rubric_item_id":"R18","check":"substring","category":"deterministic","criterion":"The document treats access and identity management as a transition control.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Day 1 or transition-control content.","grader_hint":"Look for joiner, leaver, privileged access, shared accounts, or equivalent control coverage."},{"rubric_item_id":"R19","check":"substring","category":"deterministic","criterion":"The document addresses backup, recovery, or operational resilience for critical surveying services.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Continuity finding or integration condition.","grader_hint":"The artifact should require evidence or an interim control, not simply say resilience is important."},{"rubric_item_id":"R20","check":"relational_predicate","category":"deterministic","criterion":"Transition controls include a way to identify and protect business-critical applications and data.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Transition plan or condition.","grader_hint":"Accept an application/data criticality inventory, service ownership, protected migration scope, or equivalent."},{"rubric_item_id":"R21","check":"substring","category":"deterministic","criterion":"The document addresses data migration, access, or retention as a distinct integration concern.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Integration conditions.","grader_hint":"Look for data ownership, integrity, access continuity, retention, or migration validation."},{"rubric_item_id":"R22","check":"relational_predicate","category":"deterministic","criterion":"The proposed transition approach preserves service continuity while ownership and systems are changing.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Transition-state description.","grader_hint":"Judge whether the plan recognises that systems cannot simply be switched off at completion."},{"rubric_item_id":"R23","check":"substring","category":"deterministic","criterion":"The artifact assigns an accountable owner or accountable function to the licence-resolution condition.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Condition register or responsibility labels.","grader_hint":"Accept named role or function such as legal, technology, deal lead, or vendor management; an ownerless action does not satisfy."},{"rubric_item_id":"R24","check":"relational_predicate","category":"deterministic","criterion":"Material conditions have timing tied to a meaningful milestone such as signing, completion, Day 1, or post-close integration.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Condition timing column or narrative.","grader_hint":"Timing must distinguish pre-decision, pre-completion, transition, and end-state needs where applicable."},{"rubric_item_id":"R25","check":"substring","category":"deterministic","criterion":"The document states what evidence or decision gate would close the licence condition.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Condition acceptance or exit criterion.","grader_hint":"Accept written consent, assignability confirmation, replacement plan, or a documented committee-approved alternative with an explicit test."},{"rubric_item_id":"R26","check":"substring","category":"deterministic","criterion":"The artifact identifies escalation or decision authority for an unresolved material condition.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Escalation language.","grader_hint":"Look for who decides whether to pause, condition, renegotiate, replace, or accept residual risk."},{"rubric_item_id":"R27","check":"relational_predicate","category":"deterministic","criterion":"The document distinguishes a condition to proceed from a post-close improvement backlog.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Recommendation and condition classification.","grader_hint":"The most consequential blockers must not be buried among discretionary enhancements."},{"rubric_item_id":"R28","check":"substring","category":"deterministic","criterion":"The document identifies a target-state technology ownership or governance model.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"End-state section.","grader_hint":"Accept accountable service ownership, architecture governance, vendor management, or equivalent operating-model clarity."},{"rubric_item_id":"R29","check":"relational_predicate","category":"deterministic","criterion":"The target state is not presented as achievable immediately where transition dependencies remain.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Transition versus target-state language.","grader_hint":"The document should sequence or qualify the target state rather than collapse it into a Day 1 promise."},{"rubric_item_id":"R30","check":"substring","category":"deterministic","criterion":"The summary states the scope and limitations of the diligence evidence.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Evidence basis or limitations statement.","grader_hint":"It should acknowledge the unorganised data room and absence of a complete buyer-validated inventory or equivalent limitation."},{"rubric_item_id":"R31","check":"relational_predicate","category":"deterministic","criterion":"The document separates confirmed evidence, management assertion, assumption, and unresolved unknown.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Labels or disciplined wording throughout the artifact.","grader_hint":"Judge whether a committee reader can tell what is known versus inferred or still requiring validation."},{"rubric_item_id":"R32","check":"substring","category":"deterministic","criterion":"The document identifies the source type or evidence trail for the licence concern without claiming a supplied file was fully reviewed.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Licence finding wording.","grader_hint":"It may refer to an invoice annex or contract evidence as a diligence lead, while accurately flagging the need for validation."},{"rubric_item_id":"R33","check":"constraint_predicate","category":"deterministic","criterion":"No unsupported purchase price, savings, headcount, probability, incident count, licence fee, or other precise transaction figure is invented.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"All numeric claims in the PDF.","grader_hint":"Known contextual quantities such as roughly 600 files and the 4 September meeting may be used; unsupported deal metrics must not be fabricated."},{"rubric_item_id":"R34","check":"relational_predicate","category":"deterministic","criterion":"Any quantitative statement is either sourced to the stated context, clearly labelled as an assumption, or expressed qualitatively.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Numbers and labels in the artifact.","grader_hint":"Do not award if invented estimates are presented as diligence facts."},{"rubric_item_id":"R35","check":"substring","category":"deterministic","criterion":"The recommendation explains why the licence issue and other priority risks lead to the selected decision.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Decision rationale.","grader_hint":"The conclusion must be reasoned, not merely asserted."},{"rubric_item_id":"R36","check":"relational_predicate","category":"deterministic","criterion":"The recommendation is proportionate to uncertainty and does not treat an unresolved issue as either harmless or proven fatal without rationale.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Decision wording and risk treatment.","grader_hint":"Judge whether the selected posture appropriately uses conditions, escalation, or residual-risk acceptance."},{"rubric_item_id":"R37","check":"substring","category":"deterministic","criterion":"The three slides cover decision, priority risks and conditions, and transition/end-state implications in a coherent sequence.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Rendered slides.","grader_hint":"The slides should function as a compact committee narrative rather than three unrelated pages."},{"rubric_item_id":"R38","check":"judge","category":"semantic","criterion":"The artifact is executive-usable: key decision, material risk, condition, owner, and timing can be found quickly.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Rendered PDF and navigation of content.","grader_hint":"Judge hierarchy, compression, legibility, and whether a cross-functional reader can act without asking the author to translate it."},{"rubric_item_id":"R39","check":"constraint_predicate","category":"deterministic","criterion":"The summary does not become a catalogue of all diligence files or a general technology inventory.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"First-page content.","grader_hint":"It should select decision-relevant matters and explain their implications."},{"rubric_item_id":"R40","check":"substring","category":"deterministic","criterion":"The artifact includes an explicit transition-period control for the critical survey-processing capability.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Day 1 or interim-control section.","grader_hint":"Accept continuity assurance, approved temporary use, controlled access, fallback capability, or an equivalent concrete safeguard."},{"rubric_item_id":"R41","check":"substring","category":"deterministic","criterion":"The artifact states a non-assertion or limitation alongside the licence rule, making clear that identifying a change-of-control trigger does not itself prove termination.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Licence discussion.","grader_hint":"Look for a distinction between a contractual trigger, an actual termination, and the need for legal or vendor confirmation."},{"rubric_item_id":"R42","check":"substring","category":"deterministic","criterion":"The artifact states a non-assertion or limitation alongside security concerns, making clear that an identified control gap does not itself prove a breach.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Security discussion.","grader_hint":"The document must avoid converting an evidence gap or weakness into an unsupported incident claim."},{"rubric_item_id":"R43","check":"substring","category":"deterministic","criterion":"The artifact states a non-assertion or limitation alongside continuity planning, making clear that a fallback plan does not prove recovery capability has been tested.","weight":2.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Resilience discussion.","grader_hint":"Accept explicit qualification that documented or proposed recovery is not evidence of successful testing."},{"rubric_item_id":"R44","check":"judge","category":"semantic","criterion":"The document ends on the single decision and does not close with an unprioritised next-steps list.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Final sentence or final visual element.","grader_hint":"Conditions may be embedded in the decision, but the ending must resolve the recommendation rather than defer it."},{"rubric_item_id":"R45","check":"constraint_predicate","category":"deterministic","criterion":"The document remains within the requested physical limits while retaining readable text and usable slide presentation.","weight":3.0,"polarity":"credit","scaffolding":false,"cross_deliverable":false,"required":false,"evidence":"Rendered PDF dimensions and visual inspection.","grader_hint":"Do not award if the one-page summary spills over, if there are more than three slides, or if compression makes the material practically unreadable."}],"spec":{"professional_context":"This is an enterprise IT diligence and integration decision for a professional-services transaction, where software rights, operational continuity, cyber exposure, and separation of ownership can affect the investment decision. The artifact is intended for cross-functional executives who need a defensible decision and executable conditions rather than a catalogue of diligence observations.","difficulty_sources":["materially incomplete diligence context with no supplied reference files","a buried change-of-control software-licence risk that must be distinguished from more visible but less decision-relevant findings","a transition state that must be addressed without confusing interim controls with the target operating model","the term \"Day 1\" has two plausible meanings for cross-functional stakeholders and must be defined before use","the memorandum must make one defensible investment-committee recommendation without inventing transaction facts or financial values","the document must fit a one-page summary and three-slide presentation format in a single file"],"authoring_plan":{"purpose":"Create a compact doctrinal IT diligence decision artifact for the named acquisition scenario. The gold should reward disciplined claims, explicit non-claims, and a defensible conditional decision without requiring invented transaction facts.","reference_files":[],"gold_construction":{"format":"Build one PDF with page one as a self-contained executive summary and pages two through four as exactly three slides. Use synthetic but clearly labelled assumptions only where needed to illustrate decision logic; do not introduce unsupported numeric deal facts.","core_decision":"The reference solution should normally recommend proceeding subject to explicit conditions, with the survey-processing licence treated as a gating or escalated condition because continued lawful use after change of control is unresolved. A different recommendation may pass if it is singular, proportionate, and defensibly tied to the uncertainty.","required_doctrinal_pairings":[{"rule":"A change-of-control clause or assignment restriction can make continued use of a critical software capability uncertain and therefore requires confirmation, consent, replacement, or an explicitly approved risk decision.","must_not_claim":"The presence of a trigger proves that the licence has already terminated or that the transaction is legally blocked."},{"rule":"An access or security control gap should receive a proportionate transition control and validation owner.","must_not_claim":"A control gap by itself proves a security incident or breach."},{"rule":"A continuity or recovery requirement should be tested or evidenced before it is relied upon.","must_not_claim":"A written fallback plan proves that recovery capability works."},{"rule":"A Day 1 control is an interim operating safeguard, not automatically the target-state architecture.","must_not_claim":"The interim arrangement is the final integrated operating model."}],"professional_content_constraints":["Include the critical survey-processing licence risk and its business-continuity consequence.","Include licence entitlement and ownership validation.","Include proportionate security and identity/access transition controls.","Include backup, recovery, or resilience validation for critical services.","Include data migration/access/retention considerations.","Include contractor or third-party dependency considerations.","Separate evidence, assumptions, unknowns, conditions, owners, timing, and escalation.","State what evidence closes the licence condition.","Distinguish pre-decision or pre-completion gates from Day 1 controls and longer-term end-state work.","End on one recommendation rather than a deferred action list."],"arbitrary_conventions":"No private codes, invented sheet names, or exact answer values are required. The only required filename is supplied in the request. Use ordinary professional labels such as owner, timing, evidence, condition, assumption, unknown, and escalation.","review_method":"Render the PDF and inspect page count, page-one fit, slide count, legibility, consistency of recommendation, first-use definition of Day 1, and the doctrinal rule/non-assertion pairings. Then evaluate each rubric item from the submitted artifact alone."}},"design_constraints":{"artifact_scope":"single_artifact","structure":"supplied_template"},"reference_files":[],"deliverables":[{"deliverable_id":"it_diligence_committee_pdf","filename":"stellwyn_cranmere_it_diligence_committee.pdf","media_type":"application/pdf","description":"A single PDF containing a one-page IT diligence summary with integration conditions and exactly three presentation-style slides for the investment committee.","required":true,"constraints":["The summary must occupy exactly one page.","The presentation portion must contain exactly three slides or three clearly separated slide pages.","The recommendation must be singular, explicit, and consistent across the summary and slides.","The document must distinguish evidence, assumptions, unknowns, conditions, owners, timing, and escalation.","The document must define Day 1 before using the term operationally.","The document must not invent unsupported transaction, financial, licensing, security, or operational facts."],"rendering_required":true}],"work_activity":"plan_work","work_product":"decision_memo","internet_policy":"forbidden","evidence_policy":"professional_judgment"},"source_metadata":{"prompt_version":"authored_doc@v4","occupation":"computer_information_systems_managers","sector":"professional_scientific_technical_services","task_archetype":"authored_doc","estimated_professional_hours":3.5,"gold_policy_self_report_not_verified":{"author_type":"domain_expert","reviewer_policy":"Have an IT transaction-diligence practitioner and an executive communications reviewer independently inspect the rendered PDF against every criterion, then reconcile disagreements. Treat unsupported factual assertions as failures of evidence discipline, while allowing different professional wording and different but defensible condition sequencing.","minimum_reviewers":2,"known_limitations":["No reference files are supplied, so the gold standard must evaluate professional treatment of the scenario rather than exact extracted facts.","Different defensible recommendations may be possible; the artifact must still make one recommendation and justify it proportionately.","The requested one-page summary and three-slide deck are represented as four PDF pages because only one deliverable file is allowed."],"reference_solution_passed_rubric":true}},"validation":{"label":"结构/材料验收记录","detail":"validated 属于结构、防泄漏、材料推进验收；没有内容正确率结论。","formal":false,"release_ready_recorded":true,"checks":[{"check":"package_integrity","validator":"gdpval-package","validator_version":"v1","passed":true,"required":true,"metrics":{},"evidence_artifact_ids":[],"detail":"","checked_at":"2026-08-25T03:24:03+00:00"},{"check":"gold_isolation","validator":"gdpval-package","validator_version":"v1","passed":true,"required":true,"metrics":{},"evidence_artifact_ids":[],"detail":"","checked_at":"2026-08-25T03:24:03+00:00"},{"check":"artifact_format","validator":"gdpval-package","validator_version":"v1","passed":true,"required":true,"metrics":{},"evidence_artifact_ids":[],"detail":"","checked_at":"2026-08-25T03:24:03+00:00"},{"check":"rendering","validator":"gdpval-package","validator_version":"v1","passed":true,"required":true,"metrics":{},"evidence_artifact_ids":[],"detail":"","checked_at":"2026-08-25T03:24:03+00:00"},{"check":"instruction_rubric_overlap","validator":"gdpval-package","validator_version":"v1","passed":false,"required":false,"metrics":{},"evidence_artifact_ids":[],"detail":"instruction 与 rubric criterion 存在 8-gram 逐字重叠: ['R01']","checked_at":"2026-08-25T03:24:03+00:00"}]},"source_path":"/inspire/hdd2/project/special-project-1/public/ynan/gdpval_data/corpus_c1/runs/ddf2b08ee7205962","declared_deliverables":["stellwyn_cranmere_it_diligence_committee.pdf"]};
